// Option A: include 'has_finding' in the Predicate union
type PredicateBase = (typeof PREDICATES)[keyof typeof PREDICATES][number];
export type Predicate = PredicateBase | typeof HAS_FINDING_PREDICATE;

// Option B: introduce a widened store-legal type (keeps canon separate)
type PredicateBase = (typeof PREDICATES)[keyof typeof PREDICATES][number];
export type Predicate = PredicateBase;
export type StorePredicate = Predicate | typeof HAS_FINDING_PREDICATE;
export function isPredicate(v: unknown): v is StorePredicate {
  return typeof v === 'string' && (PREDICATE_SET as Set<string>).has(v);
}

